编写一个 `Syscall Unhooking` 工具需要深入了解 Windows 内核模式和用户模式编程。EDR（Endpoint Detection and Response）工具通常通过挂钩系统调用来监控和控制系统的操作，因此恢复这些钩子是安全研究中的一个重要任务。

下面是一个基本的示例代码，展示如何从磁盘重新映射 `ntdll.dll` 以恢复被 EDR Hook 的原始函数。这个示例仅用于教育目的，请确保你有合法的权利和授权来进行此类操作，并且在遵循相关法律法规的前提下进行。

```cpp
#include <windows.h>
#include <winternl.h>

typedef NTSTATUS(WINAPI *PNtQuerySystemInformation)(
    SYSTEM_INFORMATION_CLASS SystemInformationClass,
    PVOID SystemInformation,
    ULONG SystemInformationLength,
    PULONG ReturnLength
);

typedef NTSTATUS(WINAPI *PNtCreateThreadEx)(
    PHANDLE ThreadHandle,
    ACCESS_MASK DesiredAccess,
    POBJECT_ATTRIBUTES ObjectAttributes,
    HANDLE ProcessHandle,
    PVOID StartRoutine,
    PVOID ArgumentStart,
    ULONG CreateFlags,
    SIZE_T ZeroBits,
    SIZE_T StackSize,
    SIZE_T MaximumStackSize,
    PULONG_PTR AttributeList
);

PVOID GetSyscallAddress(PCHAR SyscallName) {
    HMODULE hNtdll = LoadLibraryA("ntdll.dll");
    if (!hNtdll) return NULL;

    FARPROC pfn = GetProcAddress(hNtdll, SyscallName);
    FreeLibrary(hNtdll);

    return (PVOID)pfn;
}

PVOID GetSyscallStub(PCHAR SyscallName) {
    PVOID pAddress = GetSyscallAddress(SyscallName);
    if (!pAddress) return NULL;

    PBYTE stub = new BYTE[6];
    memcpy(stub, pAddress, 6);

    return stub;
}

BOOL UnhookFunction(PVOID OriginalFunction, PVOID HookedFunction) {
    DWORD oldProtect;
    if (!VirtualProtect(HookedFunction, 10, PAGE_EXECUTE_READWRITE, &oldProtect)) return FALSE;

    // Write the original instruction back to the hooked function
    memcpy(HookedFunction, OriginalFunction, 6);

    VirtualProtect(HookedFunction, 10, oldProtect, &oldProtect);
    return TRUE;
}

int main() {
    PNtQuerySystemInformation pNtQuerySystemInformation = (PNtQuerySystemInformation)GetSyscallAddress("NtQuerySystemInformation");
    if (!pNtQuerySystemInformation) {
        printf("Failed to get NtQuerySystemInformation address\n");
        return 1;
    }

    PVOID originalStub = GetSyscallStub("NtQuerySystemInformation");
    if (!originalStub) {
        printf("Failed to get syscall stub for NtQuerySystemInformation\n");
        return 1;
    }

    // Replace the hooked function with the original
    UnhookFunction(originalStub, pNtQuerySystemInformation);

    printf("Syscall unhooked successfully!\n");

    delete[] originalStub;
    return 0;
}
```

### 关键点解释：

1. **获取系统调用地址**：通过 `LoadLibraryA` 和 `GetProcAddress` 获取目标系统调用的地址。
2. **获取 syscall stub**：从系统调用地址复制前几个字节（通常是6个字节）作为原始指令。
3. **恢复原始函数**：将原始指令写回被挂钩的函数地址，以恢复其原始功能。

### 注意事项：

- 这个示例仅针对单个系统调用进行操作。实际应用中可能需要处理多个系统调用，并且考虑更多的边界情况和错误处理。
