### 2. 智能合约设计

首先，我们需要编写一个Solidity智能合约，用于存储和检索C2指令。以下是一个简单的示例：

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract C2Command {
    // 命令结构体
    struct Command {
        address sender;
        string commandData;
        uint256 timestamp;
    }

    // 存储命令的映射
    mapping(uint256 => Command) public commands;
    uint256 private commandCounter;

    event CommandStored(address indexed sender, uint256 indexed id);

    // 存储新命令的函数
    function storeCommand(string memory _commandData) public {
        require(bytes(_commandData).length > 0, "Command data cannot be empty");

        commands[commandCounter] = Command({
            sender: msg.sender,
            commandData: _commandData,
            timestamp: block.timestamp
        });

        emit CommandStored(msg.sender, commandCounter);
        commandCounter++;
    }

    // 获取命令的函数
    function getCommand(uint256 _id) public view returns (address, string memory, uint256) {
        require(_id < commandCounter, "Command ID out of bounds");
        Command storage cmd = commands[_id];
        return (cmd.sender, cmd.commandData, cmd.timestamp);
    }
}
```

