#### 创建`app.js`

```javascript
require('dotenv').config();
const Web3 = require('web3');
const fs = require('fs');

// 读取智能合约的ABI和字节码
const contractPath = './build/contracts/C2Command.json';
const contractJson = JSON.parse(fs.readFileSync(contractPath));
const abi = contractJson.abi;
const bytecode = contractJson.bytecode;

// 连接到本地或远程的Ethereum节点
const web3 = new Web3(new Web3.providers.HttpProvider(process.env.INFURA_URL));

// 创建合约实例
let C2Command;
web3.eth.getAccounts().then(accounts => {
    const account = accounts[0];
    console.log(`Using account: ${account}`);

    // 部署合约（如果尚未部署）
    const deployContract = async () => {
        const deployedContracts = await web3.eth.getCode(contractJson.networks['1'].address);
        if (deployedContracts === '0x') {
            const Contract = new web3.eth.Contract(abi);
            const deployTx = Contract.deploy({ data: bytecode });
            const receipt = await deployTx.send({ from: account, gas: 4700000 });
            console.log('Contract deployed at:', receipt.options.address);
        } else {
            C2Command = new web3.eth.Contract(abi, contractJson.networks['1'].address);
            console.log('Connected to existing contract at:', contractJson.networks['1'].address);
        }
    };

    deployContract().then(() => {
        // 存储命令
        const storeCommand = async () => {
            const commandData = 'some_command_data';
            const txReceipt = await C2Command.methods.storeCommand(commandData).send({ from: account, gas: 100000 });
            console.log('Command stored with transaction hash:', txReceipt.transactionHash);
        };

        storeCommand();

        // 获取命令
        C2Command.events.CommandStored({}, (error, event) => {
            if (error) {
                console.error('Event error:', error);
                return;
            }
            console.log('New command stored:', event.returnValues);
        });
    });
});
```

